import{z as l,x as B,o,c as d,q as i,j as s,D as t,d as E,s as n,S as p,b as r}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"Hopcroft–Karp","description":"","frontmatter":{"title":"Hopcroft–Karp","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hopcroft-karp.md","filePath":"cs/hopcroft-karp.md","lastUpdated":1791063341000}'),c={name:"cs/hopcroft-karp.md"};function A(D,a,h,f,m,u){const e=B("Mermaid");return o(),d("div",null,[a[2]||(a[2]=i('<h1 id="hopcroft–karp" tabindex="-1">Hopcroft–Karp <a class="header-anchor" href="#hopcroft–karp" aria-label="Permalink to &quot;Hopcroft–Karp&quot;">​</a></h1><div class="epigraph"><p>二分图上一次 BFS 找出全体最短增广路，再 DFS 同时增广，相位 $O(\\sqrt V)$，总 $O(E\\sqrt V)$。</p><footer>—— 据 Hopcroft and Karp, An $n^{5/2}$ Algorithm for Maximum Matchings in Bipartite Graphs, 1973；CLRS 第 26.3 节整理</footer></div><p>上一课<a href="/cs/min-cut-applications">最小割的建模</a>把划分交给最大流。主干<a href="/cs/bipartite-match">二分图匹配</a>已用单位容量流给出最大匹配。缺口是<strong>更快的增广组织</strong>：Hopcroft–Karp 与单位网络上 Dinic 同类，不把每条交错路单独 BFS 到底。不重写 König。后课带权匹配。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>匈牙利：一次找一条增广路 \\(O(E)\\)，最多 \\(V\\) 次，\\(O(VE)\\)。Hopcroft–Karp：残量（自由点、\\(L\\to R\\) 非匹配、\\(R\\to L\\) 匹配）上 BFS，只保留到自由 \\(R\\) 的最短距离分层；再在分层里 DFS 找极大一组<strong>顶点不交</strong>的最短增广，同时翻转。相位数 \\(O(\\sqrt V)\\)：短增广做完后，剩余增广至少长 \\(\\sqrt V\\) 量级，条数受匹配规模限制。总 \\(O(E\\sqrt V)\\)。</p><p>缺口是「一批最短」，不是新的匹配定义。Berge 增广路定理仍是正确性根。</p><h3 id="与-dinic-同一张分层" tabindex="-1">与 Dinic 同一张分层 <a class="header-anchor" href="#与-dinic-同一张分层" aria-label="Permalink to &quot;与 Dinic 同一张分层&quot;">​</a></h3><p>单位容量 \\(s\\)–\\(L\\)–\\(R\\)–\\(t\\) 上 Dinic 的阻塞流，在二分匹配里就是这批最短增广。本课用匹配语言写，便于后课 KM、带花对照。不要声称一般图也 \\(O(E\\sqrt V)\\)——一般图要 Micali–Vazirani 等，更重。</p><p><span class="marginnote">Hopcroft–Karp 1973。Dinic 1970 更早给出分层阻塞流。CLRS 26.3 用流，竞赛实现常写 HK 的 BFS+DFS。后课 Kuhn–Munkres 处理权。</span></p><p><span class="marginnote">术语翻译：增广路是一条「未匹配边、匹配边、未匹配边……」交替的路，首尾都是自由点；把路上两种边的身份对调（翻转），匹配数恰好多 1。Berge 定理说：再也找不到增广路，匹配就已是最大。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>重复：从全体自由 \\(L\\) BFS 分层，若无自由 \\(R\\) 则停。DFS 从自由 \\(L\\) 沿层 \\(+1\\) 边增广，点用过即占用。翻转匹配边。直到 BFS 失败。</p>',12)),(o(),s(p,null,{default:t(()=>[n(e,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20BFS%5B%22BFS%20%E6%9C%80%E7%9F%AD%E5%88%86%E5%B1%82%22%5D%20--%3E%20DFS%5B%22%E5%90%8C%E6%97%B6%E5%A4%9A%E6%9D%A1%E6%9C%80%E7%9F%AD%E5%A2%9E%E5%B9%BF%22%5D%0A%20%20DFS%20--%3E%20M%5B%22%E6%9B%B4%E6%96%B0%E5%8C%B9%E9%85%8D%22%5D%0A%20%20M%20--%3E%20BFS%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("p",null,"实现注意：一轮内每个点至多一次。",-1)),a[4]||(a[4]=r("h2",{id:"机制",tabindex:"-1"},[E("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=r("p",null,"最短增广长度不减。一轮吃掉该长度的极大不交组后，下一轮更长。分析把相位分成「短于 \\(\\sqrt V\\)」与之后，得到 \\(O(\\sqrt V)\\) 轮。与普通匈牙利比，只改调度，不改交错路翻转。",-1)),a[6]||(a[6]=r("p",null,"一轮 BFS 分层长什么样：",-1)),(o(),s(p,null,{default:t(()=>[n(e,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E8%87%AA%E7%94%B1%20L%20%E7%82%B9%E5%85%A8%E4%BD%93%22%5D%20--%3E%20L0%5B%22%E5%B1%82%200%3A%20%E8%87%AA%E7%94%B1%20L%22%5D%0A%20%20L0%20--%3E%20L1%5B%22%E5%B1%82%201%3A%20%E6%B2%BF%E9%9D%9E%E5%8C%B9%E9%85%8D%E8%BE%B9%E5%88%B0%20R%22%5D%0A%20%20L1%20--%3E%20L2%5B%22%E5%B1%82%202%3A%20%E6%B2%BF%E5%8C%B9%E9%85%8D%E8%BE%B9%E9%80%80%E5%9B%9E%20L%22%5D%0A%20%20L2%20--%3E%20L3%5B%22%E5%B1%82%203%3A%20%E5%86%8D%E6%B2%BF%E9%9D%9E%E5%8C%B9%E9%85%8D%E8%BE%B9%E5%88%B0%20R%22%5D%0A%20%20L3%20--%3E%20T%7B%22%E8%BF%99%E5%B1%82%E6%9C%89%E8%87%AA%E7%94%B1%20R%3F%22%7D%0A%20%20T%20--%20%22%E6%9C%89%22%20--%3E%20S%5B%22%E5%8F%AA%E7%95%99%E6%9C%80%E7%9F%AD%E5%B1%82%2C%20DFS%20%E6%89%BE%E4%B8%8D%E4%BA%A4%E5%A2%9E%E5%B9%BF%22%5D%0A%20%20T%20--%20%22%E6%B2%A1%E6%9C%89%22%20--%3E%20X%5B%22BFS%20%E5%A4%B1%E8%B4%A5%3A%20%E5%8C%B9%E9%85%8D%E5%B7%B2%E6%9C%80%E5%A4%A7%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<p><span class="marginnote">数字实例：\\(V=10^4\\)、\\(E=10^5\\) 的二分图，匈牙利 \\(O(VE)\\) 约 \\(10^9\\)，HK 的 \\(O(E\\sqrt V)=10^5\\times10^2=10^7\\)，差出百倍——把相位从最多 \\(V\\) 轮压到约 \\(100\\) 轮，就是全部秘密。</span></p><p>稠密图 \\(E=\\Theta(V^2)\\) 时 \\(O(V^{2.5})\\)，仍优于 \\(O(VE)\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写一般图匹配、不写带权。不把 Hall 条件再证一遍。后课默认：二分最大基数匹配实用 \\(O(E\\sqrt V)\\)。下一课 KM / 匈牙利带权。</p><p><span class="marginnote">直觉类比：HK 像「扫地先扫近处」——每轮只处理当前最短的增广路，且把互不妨碍（顶点不交）的一批一把扫完；短的全扫完，剩下的路必然越来越长，而长路条数有限（\\(\\sqrt V\\) 量级），轮数于是被封死。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一批最短增广 = 二分匹配的 Dinic。</li><li>\\(O(E\\sqrt V)\\)；正确性仍是增广路定理。</li><li>一般图不是本课的界。</li><li>出处：Hopcroft and Karp, 1973。</li></ul>',7))])}const V=l(c,[["render",A]]);export{F as __pageData,V as default};
